#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        if (nums.empty()) return 0;
        std::unordered_map<int, int> freq;
        int max_f = 0;
        for (int x : nums) {
            max_f = std::max(max_f, ++freq[x]);
        }
        return nums.size() - max_f;
    }
};

import java.util.*;

class Solution {
    public int minOperations(int[] nums) {
        if (nums.length == 0) return 0;
        Map<Integer, Integer> freq = new HashMap<>();
        int maxF = 0;
        for (int x : nums) {
            int count = freq.getOrDefault(x, 0) + 1;
            freq.put(x, count);
            maxF = Math.max(maxF, count);
        }
        return nums.length - maxF;
    }
}

var minOperations = function(nums) {
    if (nums.length === 0) return 0;
    const freq = new Map();
    let maxF = 0;
    for (const x of nums) {
        const count = (freq.get(x) || 0) + 1;
        freq.set(x, count);
        if (count > maxF) maxF = count;
    }
    return nums.length - maxF;
};
